const M6_DISPLAY_ROWS: Record<string, string[][]> = {
  '3-1': [['Baking', '9'], ['Sports', '16'], ['Chorus', '13'], ['Drama', '18']],
  '4-1': [['Ben', '300'], ['Rachel', '250'], ['Jeff', '100'], ['Stanley', '450'], ['Debbie', '600']],
  '9-1': [['Stewart', '16'], ['Roxanne', '____'], ['Trisha', '12'], ['Philip', '20'], ['Total', '72']]
};

function m6DataValues(labels: string[], counts: number[]): string[] {
  return labels.flatMap((label, index) => Array.from({ length: counts[index] ?? 0 }, () => label));
}

function m6LinePlot(title: string, labels: string[], counts?: number[], keyLabel = 'X = 1 item', options: Partial<ProblemSetDataDisplay> = {}) {
  return {
    kind: 'line-plot' as const,
    title,
    values: labels.map((label, index) => ({ label, value: counts?.[index] ?? 0 })),
    keyLabel,
    ...options
  };
}

function m6BarGraph(title: string, values: Array<{ label: string; value: number }>, maxValue: number, scaleLabel: string) {
  return {
    kind: 'bar-graph' as const,
    title,
    values,
    maxValue,
    scaleLabel
  };
}

function m6ProblemDisplay(lessonNumber: number, problemNumber: number) {
  const key = `${lessonNumber}-${problemNumber}`;
  if (lessonNumber === 1) {
    return {
      kind: problemNumber === 3 || problemNumber === 4 ? 'picture-graph' as const : 'tally-picture' as const,
      title: 'Favorite Colors',
      columns: ['Color', 'Number of Students'],
      categories: ['Green', 'Yellow', 'Red', 'Blue', 'Orange'],
      keyLabel: problemNumber === 3 || problemNumber === 4 ? 'Each symbol represents 1 student in 3(a) or 2 students in 3(b).' : 'Survey data is variable by class.'
    };
  }
  if (lessonNumber === 2) {
    return {
      kind: 'vertical-tape' as const,
      title: 'Stamps by Student',
      values: [
        { label: 'Dana', value: 16 },
        { label: 'Tanisha', value: problemNumber === 1 ? 0 : 8 },
        { label: 'Raquel', value: problemNumber === 1 ? 0 : 24 },
        { label: 'Anna', value: problemNumber === 1 ? 0 : 32 }
      ],
      unitSize: problemNumber === 3 ? 8 : 4,
      scaleLabel: problemNumber === 3 ? 'Each unit is 8 stamps in Problem 3(b).' : 'Each unit is 4 stamps.'
    };
  }
  if (key === '3-1') {
    return { kind: 'data-table' as const, title: 'Number of Students in Each Class', columns: ['Class', 'Number of Students'], rows: M6_DISPLAY_ROWS[key], note: 'Color the bar graph using the table values.' };
  }
  if (key === '3-2' || key === '3-3') {
    return m6BarGraph('Kyle’s Savings', [
      { label: 'February', value: 30 },
      { label: 'March', value: 46 },
      { label: 'April', value: 23 },
      { label: 'May', value: 34 },
      { label: 'June', value: 40 }
    ], 50, 'Scale: dollars from 0 to 50 by 5.');
  }
  if (key === '3-4' || key === '3-5') {
    return m6BarGraph('Charlotte’s Reading Minutes', [
      { label: 'Monday', value: 50 },
      { label: 'Tuesday', value: 50 },
      { label: 'Wednesday', value: 70 },
      { label: 'Thursday', value: 50 },
      { label: 'Friday', value: 40 }
    ], 70, 'Scale: minutes from 0 to 70 by 10.');
  }
  if (key === '4-1') {
    return { kind: 'data-table' as const, title: 'Number of Magazines Sold by Third-Grade Students', columns: ['Student', 'Magazines Sold'], rows: M6_DISPLAY_ROWS[key], note: 'Choose a scale that can show values from 100 to 600.' };
  }
  if (key === '4-2') {
    return m6BarGraph('Carnival Visitors', [
      { label: 'Monday', value: 340 },
      { label: 'Tuesday', value: 300 },
      { label: 'Wednesday', value: 430 },
      { label: 'Thursday', value: 190 },
      { label: 'Friday', value: 370 }
    ], 500, 'Scale: visitors from 0 to 500 by 50; minor tick marks show tens.');
  }
  if (lessonNumber === 5) {
    return {
      kind: 'ruler' as const,
      title: problemNumber === 1 ? 'Measurement Chart and Ruler Intervals' : 'Jenna’s 5-inch Paper Strip',
      ticks: ['0', '1/4', '1/2', '3/4', '1', '1 1/4', '1 1/2', '1 3/4', '2', '2 1/4', '2 1/2', '2 3/4', '3', '3 1/4', '3 1/2', '3 3/4', '4', '4 1/4', '4 1/2', '4 3/4', '5'],
      note: 'Whole inches, half inches, and quarter inches are marked on the same 5-inch strip.'
    };
  }
  if (key === '6-1') {
    return m6LinePlot('Heights of Children on Third-Grade Basketball Team', ['51', '51 1/2', '52', '52 1/2', '53', '53 1/2', '54', '54 1/2', '55'], [2, 0, 3, 1, 2, 3, 1, 2, 1], 'X = 1 child', {
      showBlankValues: true,
      note: 'This line plot is given in the official Problem Set.'
    });
  }
  if (key === '6-2') {
    return m6LinePlot('Lengths of Worms', ['3', '3 1/4', '3 2/4', '3 3/4', '4', '4 1/4', '4 2/4', '4 3/4', '5'], [1, 2, 4, 6, 8, 4, 3, 0, 2], 'X = 1 worm', {
      showBlankValues: true,
      note: 'This line plot is given in the official Problem Set.'
    });
  }
  if (lessonNumber === 7) {
    const labels = ['1 3/4', '2', '2 1/4', '2 1/2', '2 3/4', '3', '3 1/4'];
    const counts = [4, 2, 3, 3, 2, 3, 3];
    return m6LinePlot('Heights of Bean Plants', labels, problemNumber === 1 ? counts : undefined, 'X = 1 bean plant', {
      sourceData: m6DataValues(labels, counts),
      sourceDataRows: [
        ['2 1/4', '2 3/4', '3 1/4', '1 3/4', '1 3/4'],
        ['1 3/4', '3', '2 1/2', '3 1/4', '2 1/2'],
        ['2', '2 1/4', '3', '2 1/4', '3'],
        ['2 1/2', '3 1/4', '1 3/4', '2 3/4', '2']
      ],
      note: 'Use the source data values to complete the blank line plot.'
    });
  }
  if (lessonNumber === 8) {
    const labels = ['5 1/2', '5 3/4', '6', '6 1/4', '6 1/2', '6 3/4'];
    const counts = [1, 5, 8, 6, 4, 1];
    return m6LinePlot('Widths of Silver Maple Tree Leaves', labels, problemNumber === 1 ? counts : undefined, 'X = 1 leaf', {
      sourceData: m6DataValues(labels, counts),
      sourceDataRows: [
        ['5 3/4', '6', '6 1/4', '6', '5 3/4'],
        ['6 1/2', '6 1/4', '5 1/2', '5 3/4', '6'],
        ['6 1/4', '6', '6', '6 1/2', '6 1/4'],
        ['6 1/2', '5 3/4', '6 1/4', '6', '6 3/4'],
        ['6', '6 1/4', '6', '5 3/4', '6 1/2']
      ],
      note: 'Use the source data values to create the blank line plot.'
    });
  }
  if (key === '9-1' || key === '9-2') {
    return {
      kind: 'picture-graph' as const,
      title: 'Apples Picked',
      columns: ['Name', 'Number of Apples Picked'],
      rows: M6_DISPLAY_ROWS['9-1'],
      values: [
        { label: 'Stewart', value: 16 },
        { label: 'Roxanne', value: 24 },
        { label: 'Trisha', value: 12 },
        { label: 'Philip', value: 20 }
      ],
      unitSize: 4,
      keyLabel: 'Valid key shown: each symbol represents 4 apples.'
    };
  }
  if (key === '9-3') {
    const labels = ['2', '2 1/4', '2 1/2', '2 3/4', '3', '3 1/4', '3 1/2', '3 3/4'];
    const counts = [1, 3, 2, 6, 4, 5, 0, 3];
    return m6LinePlot('Lengths of Blades of Grass', labels, counts, 'X = 1 blade of grass', {
      sourceData: m6DataValues(labels, counts),
      sourceDataRows: [
        ['2 1/4', '2 3/4', '3 1/4', '3', '2 1/2', '2 3/4'],
        ['2 3/4', '3 3/4', '2', '2 3/4', '3 3/4', '3 1/4'],
        ['3', '2 1/2', '3 1/4', '2 1/4', '2 3/4', '3'],
        ['3 1/4', '2 1/4', '3 3/4', '3', '3 1/4', '2 3/4']
      ],
      note: 'Use the source data values to make the blank line plot.'
    });
  }
  return {
    kind: 'data-table' as const,
    title: M6_VISUAL_FAMILY[lessonNumber] ?? 'Data display',
    note: 'Complete the official data display from the prompt.'
  };
}

function m6SolvedProblemDisplay(lessonNumber: number, problemNumber: number, display: ProblemSetDataDisplay): ProblemSetDataDisplay {
  if (lessonNumber === 6 && problemNumber === 2) {
    return m6LinePlot('Lengths of Worms after Madeline Adds Her Worm', ['3', '3 1/4', '3 2/4', '3 3/4', '4', '4 1/4', '4 2/4', '4 3/4', '5'], [1, 2, 4, 6, 8, 4, 3, 1, 2], 'X = 1 worm', {
      showBlankValues: true,
      note: 'Solved line plot includes Madeline’s new 4 3/4-inch worm.'
    });
  }
  if (lessonNumber === 2 && problemNumber === 1) {
    return {
      ...display,
      values: [
        { label: 'Dana', value: 16 },
        { label: 'Tanisha', value: 8 },
        { label: 'Raquel', value: 24 },
        { label: 'Anna', value: 32 }
      ]
    };
  }
  if (lessonNumber === 9 && (problemNumber === 1 || problemNumber === 2) && display.rows?.length) {
    return {
      ...display,
      rows: display.rows.map((row) => row.map((cell) => cell === '____' ? '24' : cell))
    };
  }
  return display;
}

function m6BlankVisualType(display: ReturnType<typeof m6ProblemDisplay>): ProblemSetCenteredLesson['problems'][number]['blankVisualType'] {
  if (display.kind === 'tally-picture' || display.kind === 'picture-graph') {
    return 'tally-picture-graph-template';
  }
  if (display.kind === 'vertical-tape') {
    return 'vertical-tape-display-template';
  }
  if (display.kind === 'ruler') {
    return 'ruler-template';
  }
  if (display.kind === 'line-plot') {
    return 'line-plot-template';
  }
  if (display.kind === 'bar-graph') {
    return 'bar-graph-template';
  }
  return 'data-table-template';
}

function m6MaskBlankEquation(equation: string): string {
  return equation
    .replace(/×/g, 'x')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\b\d[\d,]*(?:\.\d+)?\b/g, '____');
}

function m6BlankEquationTemplates(sourceEquations: string[], visualFamily: string): string[] {
  const templates = sourceEquations
    .map((equation) => {
      const normalized = equation.replace(/×/g, 'x').replace(/\s+/g, ' ').trim();
      return normalized.includes('____') ? normalized : m6MaskBlankEquation(normalized);
    })
    .filter(Boolean);

  return templates.length
    ? Array.from(new Set(templates))
    : [`Use the official ${visualFamily} blanks and explain from the display evidence.`];
}

function m6ReviewedLessonsOneThroughFiveVisual(
  lessonNumber: number,
  problemNumber: number,
  sourcePrompt: string,
  solvedAnswer: string | undefined,
  solved: boolean
): ProblemVisualSpec | undefined {
  if (lessonNumber < 1 || lessonNumber > 5) {
    return undefined;
  }
  const sections: ProblemVisualSpec['sections'] = [];
  const table = (label: string, columns: string[], rows: string[][]): ProblemVisualSpec['sections'][number] => ({
    kind: 'data-table',
    label,
    columns,
    rows
  });
  const response = (
    label: string,
    solvedLines: string[],
    printedLineCount: number
  ): ProblemVisualSpec['sections'][number] => ({
    kind: 'source-response-workspace',
    label,
    parts: [{
      prompt: sourcePrompt,
      lines: solved ? solvedLines : [],
      printedLineCount,
      openWorkspace: !solved
    }]
  });
  const chart = (
    label: string,
    values: Array<{ label: string; value?: number; valueLabel?: string }>,
    options: {
      chart?: 'bar' | 'picture' | 'tally';
      maxValue?: number;
      unitSize?: number;
      scaleLabel?: string;
      keyLabel?: string;
      showBlankValues?: boolean;
      caption?: string;
    } = {}
  ): ProblemVisualSpec['sections'][number] => ({
    kind: 'data-chart',
    chart: options.chart ?? 'bar',
    label,
    values,
    maxValue: options.maxValue,
    unitSize: options.unitSize,
    scaleLabel: options.scaleLabel,
    keyLabel: options.keyLabel,
    showBlankValues: options.showBlankValues ?? false,
    caption: options.caption
  });
  const line = (
    label: string,
    labels: string[],
    targets: string[] = [],
    caption = ''
  ): ProblemVisualSpec['sections'][number] => ({
    kind: 'number-line',
    label,
    ticks: labels.map((tickLabel) => ({ label: tickLabel, target: targets.includes(tickLabel) })),
    caption
  });
  const sourceCrop = (
    label: string,
    src: string,
    crop: { x: number; y: number; width: number; height: number },
    alt: string,
    caption: string
  ): ProblemVisualSpec['sections'][number] => ({
    kind: 'source-crop',
    label,
    src,
    alt,
    imageWidth: 1020,
    imageHeight: 1320,
    crop,
    caption
  });
  const tapeCards = (
    label: string,
    values: Array<{ label: string; total: number; unit: number; sourceUnits?: number }>
  ): ProblemVisualSpec['sections'][number] => ({
    kind: 'card-grid',
    label,
    cards: values.map((item) => ({
      label: item.label,
      sections: [{
        kind: 'tape',
        label: `${item.label}: ${item.total} stamps`,
        totalLabel: solved || item.sourceUnits ? `${item.total} stamps` : `${item.label}: ____`,
        parts: Array.from(
          { length: solved ? item.total / item.unit : item.sourceUnits ?? 0 },
          () => ({ label: solved || item.sourceUnits ? String(item.unit) : '' })
        ),
        caption: solved
          ? `${item.total / item.unit} equal units of ${item.unit}`
          : item.sourceUnits
            ? 'Source-provided completed example retained.'
            : 'Complete the stacked equal-unit tape from the source data.'
      }]
    }))
  });
  const colors = ['Green', 'Yellow', 'Red', 'Blue', 'Orange'];
  const variableColorRows = colors.map((color) => [color, solved ? 'class survey count' : '____']);

  if (lessonNumber === 1) {
    if (problemNumber === 1) {
      sections.push(table(solved ? 'Completed class tally chart criteria' : 'Official empty class tally chart', ['Color', 'Number of Students'], variableColorRows));
      if (solved) {
        sections.push(response('Survey completion check', [
          'One response is recorded for each surveyed student.',
          'Green, Yellow, Red, Blue, and Orange are retained.',
          'No student is counted twice.'
        ], 6));
      }
    } else if (problemNumber === 2) {
      sections.push(
        table('Problem 1 tally counts used as givens', ['Color', 'Number of Students'], colors.map((color) => [color, 'read from Problem 1'])),
        response(solved ? 'Teacher Edition variable-data criteria' : 'Six official answer parts', solved ? [
          'a–b. Read orange and yellow directly from Problem 1.',
          'c–d. Identify the greatest and least tally counts with their colors.',
          'e. Subtract least from greatest and show the number sentence.',
          'f. Add all five tally counts for the surveyed total.'
        ] : [], 12)
      );
    } else if (problemNumber === 3) {
      if (solved) {
        sections.push(
          sourceCrop(
            'Official picture graph 3(a) topology',
            '/source-pages/m6/workbook-page-03.png',
            { x: 128, y: 232, width: 758, height: 427 },
            'Empty Favorite Colors picture graph with five columns and one-student heart key',
            'The source graph remains empty because the class survey counts are variable.'
          ),
          sourceCrop(
            'Official picture graph 3(b) topology',
            '/source-pages/m6/workbook-page-03.png',
            { x: 128, y: 731, width: 758, height: 427 },
            'Empty Favorite Colors picture graph with five columns and two-student heart key',
            'The source graph remains empty because the class survey counts are variable.'
          ),
          table('Picture graph 3(a) completion criteria', ['Color', 'Symbols'], colors.map((color) => [color, '1 symbol per student from Problem 1'])),
          table('Picture graph 3(b) completion criteria', ['Color', 'Symbols'], colors.map((color) => [color, '1 symbol per 2 students; half-symbol if needed']))
        );
      } else {
        sections.push(
          sourceCrop(
            'Official empty picture graph 3(a)',
            '/source-pages/m6/workbook-page-03.png',
            { x: 128, y: 232, width: 758, height: 427 },
            'Empty Favorite Colors picture graph with five columns and one-student heart key',
            'Tight graph-only crop preserves the exact five-column topology and one-student key.'
          ),
          sourceCrop(
            'Official empty picture graph 3(b)',
            '/source-pages/m6/workbook-page-03.png',
            { x: 128, y: 731, width: 758, height: 427 },
            'Empty Favorite Colors picture graph with five columns and two-student heart key',
            'Tight graph-only crop preserves the exact five-column topology and two-student key.'
          )
        );
      }
    } else {
      sections.push(
        sourceCrop(
          'Problem 3(b) graph topology retained for reference',
          '/source-pages/m6/workbook-page-03.png',
          { x: 128, y: 731, width: 758, height: 427 },
          'Favorite Colors picture graph with five columns and two-student heart key',
          solved
            ? 'The official topology is retained; the class-specific symbols remain variable.'
            : 'Use the symbols you completed in Problem 3(b); no class count is invented.'
        ),
        ...(solved
          ? [table('Problem 3(b) variable class graph used as a given', ['Color', 'Symbols'], colors.map((color) => [color, 'student work from Problem 3(b)']))]
          : []),
        response(solved ? 'Teacher Edition answer work' : 'Four official answer parts', solved ? [
          'a. Each full heart represents 2 students.',
          'b. Three students are 1 full heart and 1 half-heart.',
          'c. Seven pictured hearts represent 14 students: 7 × 2 = 14.',
          'd. The most-versus-least comparison depends on the class survey.'
        ] : [], 12)
      );
    }
    return {
      title: 'Favorite Colors: official tally and picture-graph work',
      sourceNote: solved ? 'Variable class data are checked only by the Teacher Edition criteria.' : 'Blank retains only source givens and leaves every student entry open.',
      sections
    };
  }

  const stampValues = [
    { label: 'Dana', total: 16, unit: problemNumber === 3 ? 8 : 4, sourceUnits: problemNumber === 1 ? 4 : problemNumber === 2 ? 4 : 0 },
    { label: 'Tanisha', total: 8, unit: problemNumber === 3 ? 8 : 4, sourceUnits: problemNumber === 2 ? 2 : 0 },
    { label: 'Raquel', total: 24, unit: problemNumber === 3 ? 8 : 4, sourceUnits: problemNumber === 2 ? 6 : 0 },
    { label: 'Anna', total: 32, unit: problemNumber === 3 ? 8 : 4, sourceUnits: problemNumber === 2 ? 8 : 0 }
  ];
  if (lessonNumber === 2) {
    if (problemNumber === 1) {
      sections.push(
        table('Source stamp totals counted from the four official stamp arrays', ['Student', 'Stamps'], stampValues.map((item) => [item.label, String(item.total)])),
        tapeCards('Unit-size-4 tape diagrams', stampValues),
        response(solved ? 'Teacher Edition answer work' : 'Four total labels remain open', solved ? [
          'Dana: 4 units of 4 = 16.',
          'Tanisha: 2 units of 4 = 8.',
          'Raquel: 6 units of 4 = 24.',
          'Anna: 8 units of 4 = 32.'
        ] : [], 6)
      );
    } else if (problemNumber === 2) {
      sections.push(
        tapeCards('Problem 1 horizontal tapes retained as givens', stampValues),
        response(solved ? 'Teacher Edition explanation' : 'Open explanation workspace', solved ? [
          'Turn each horizontal tape upright.',
          'Keep the same student labels and the same number of equal 4-stamp units.'
        ] : [], 8)
      );
    } else {
      const fourUnitValues = stampValues.map((item) => ({ ...item, unit: 4, sourceUnits: item.label === 'Dana' ? 4 : 0 }));
      const eightUnitValues = stampValues.map((item) => ({ ...item, unit: 8, sourceUnits: item.label === 'Dana' ? 2 : 0 }));
      sections.push(
        tapeCards('a. Vertical tapes with units of 4', fourUnitValues),
        tapeCards('b. Vertical tapes with units of 8', eightUnitValues),
        response(solved ? 'Teacher Edition answer work' : 'Parts c–g remain open', solved ? [
          'c. Valid title: Stamps by Student.',
          'd. 20 total units of 4.',
          'e. 10 total units of 8.',
          'f. Doubling each unit value halves the number of units for the same totals.',
          'g. Anna and Raquel have 4 + 3 = 7 units of 8, so 7 × 8 = 56.'
        ] : [], 14)
      );
    }
    return {
      title: 'Stamps by Student: official equal-unit tape diagrams',
      sourceNote: solved ? 'Every fixed stamp total and unit count matches the answer key.' : 'Source totals remain visible; only requested tape work and responses are open.',
      sections
    };
  }

  const kyle = [
    { label: 'February', value: 30 },
    { label: 'March', value: 46 },
    { label: 'April', value: 23 },
    { label: 'May', value: 34 },
    { label: 'June', value: 40 }
  ];
  const charlotte = [
    { label: 'Monday', value: 50 },
    { label: 'Tuesday', value: 50 },
    { label: 'Wednesday', value: 70 },
    { label: 'Thursday', value: 50 },
    { label: 'Friday', value: 40 }
  ];
  if (lessonNumber === 3) {
    if (problemNumber === 1) {
      sections.push(
        table('Number of Students in Each Class source table', ['Class', 'Number of Students'], [['Baking', '9'], ['Sports', '16'], ['Chorus', '13'], ['Drama', '18']]),
        chart('Official bar-graph workspace', ['Baking', 'Sports', 'Chorus', 'Drama'].map((label) => {
          const value = ({ Baking: 9, Sports: 16, Chorus: 13, Drama: 18 } as Record<string, number>)[label];
          return {
            label,
            value: solved ? value : label === 'Baking' ? 9 : 0,
            valueLabel: solved ? String(value) : label === 'Baking' ? '9' : '____'
          };
        }), {
          maxValue: 20,
          scaleLabel: '0 to 20 by 2 students',
          showBlankValues: true,
          caption: solved ? 'Bars match 9, 16, 13, and 18.' : 'The Baking example is 9; complete the remaining bars from the table.'
        }),
        response(solved ? 'Teacher Edition answer work' : 'Parts a–c remain open', solved ? [
          'a. Each square represents 2 students.',
          'b. 9 + 16 + 13 + 18 = 56 students.',
          'c. 13 + 9 = 22, and 22 − 16 = 6 fewer students.'
        ] : [], 10)
      );
    } else if (problemNumber === 2) {
      sections.push(
        chart('Kyle’s Savings: source-provided bar graph', kyle, {
          maxValue: 50,
          scaleLabel: 'Dollars from 0 to 50 by 5; one-dollar minor intervals.',
          showBlankValues: true,
          caption: 'All five bar heights are printed source givens.'
        }),
        response(solved ? 'Teacher Edition answer work' : 'Parts a–d remain open', solved ? [
          'a. May: $34.',
          'b. February, April, and May are less than $35.',
          'c. $40 − $23 = $17.',
          'd. April is half of March.'
        ] : [], 10)
      );
    } else if (problemNumber === 3) {
      sections.push(
        chart('Kyle’s Savings: Problem 2 graph retained as the source given', kyle, {
          maxValue: 50,
          scaleLabel: 'Dollars from 0 to 50 by 5; one-dollar minor intervals.',
          showBlankValues: true
        }),
        table(solved ? 'Completed savings table' : 'Official empty savings table', ['Month', 'Amount Saved in Dollars'], kyle.map((item) => [item.label, solved ? String(item.value) : '____']))
      );
    } else if (problemNumber === 4) {
      sections.push(
        chart('Charlotte’s Reading Minutes: source-provided graph', charlotte, {
          maxValue: 70,
          scaleLabel: 'Minutes from 0 to 70 by 10.',
          showBlankValues: true,
          caption: 'All five bar lengths are printed source givens.'
        }),
        line(
          solved ? 'Completed minutes number line' : 'Source unpartitioned number-line arrow',
          solved ? ['0', '10', '20', '30', '40', '50', '60', '70'] : ['', '', '', '', '', '', '', ''],
          solved ? ['40', '50', '70'] : [],
          solved ? 'Monday 50, Tuesday 50, Wednesday 70, Thursday 50, Friday 40.' : 'Use the graph grid as a ruler; intervals and five day labels remain open.'
        )
      );
    } else {
      sections.push(
        chart('Charlotte’s Reading Minutes: source-provided graph', charlotte, {
          maxValue: 70,
          scaleLabel: 'Minutes from 0 to 70 by 10.',
          showBlankValues: true
        }),
        response(solved ? 'Teacher Edition answer work' : 'Parts a–b remain open', solved ? [
          'a. Monday, Tuesday, and Thursday: 50 minutes.',
          'b. 70 − 40 = 30 more minutes.'
        ] : [], 8)
      );
    }
    return {
      title: lessonNumber === 3 ? 'Official scaled bar-graph evidence' : 'Data display',
      sourceNote: solved ? 'Fixed graph values and responses match the Teacher Edition answer pages.' : 'Printed graph bars remain visible; only requested construction and responses are open.',
      sections
    };
  }

  const magazine = [
    { label: 'Ben', value: 300 },
    { label: 'Rachel', value: 250 },
    { label: 'Jeff', value: 100 },
    { label: 'Stanley', value: 450 },
    { label: 'Debbie', value: 600 }
  ];
  const carnival = [
    { label: 'Monday', value: 340 },
    { label: 'Tuesday', value: 300 },
    { label: 'Wednesday', value: 430 },
    { label: 'Thursday', value: 190 },
    { label: 'Friday', value: 370 }
  ];
  if (lessonNumber === 4) {
    if (problemNumber === 1) {
      sections.push(
        table('Official magazine-sales source chart', ['Student', 'Magazines Sold'], magazine.map((item) => [item.label, String(item.value)])),
        chart(solved ? 'Completed bar graph' : 'Official empty bar-graph workspace', solved ? magazine : magazine.map((item) => ({ label: item.label, value: 0, valueLabel: '____' })), {
          maxValue: 600,
          scaleLabel: solved ? 'Valid scale: 0 to 600 by 100.' : 'Choose and label an equal-interval scale that displays 100 through 600.',
          caption: solved ? 'All five bars match the table.' : 'Scale labels and bar heights remain open.'
        }),
        response(solved ? 'Teacher Edition answer work' : 'Parts b–d remain open', solved ? [
          'b. A valid equal-interval scale shows every value from 100 to 600.',
          'c. 300 + 450 − 600 = 150 fewer.',
          'd. 600 + 100 − (300 + 250) = 150 more.'
        ] : [], 10)
      );
    } else {
      sections.push(
        chart('Carnival Visitors: source-provided bar graph', carnival, {
          maxValue: 500,
          scaleLabel: 'Visitors from 0 to 500 by 50; minor intervals are 10.',
          showBlankValues: true,
          caption: 'Every bar height is a printed source given.'
        }),
        response(solved ? 'Teacher Edition answer work' : 'Parts a–b remain open', solved ? [
          'a. 430 − 190 = 240 fewer visitors.',
          'b. (340 + 300) − (190 + 370) = 80 more visitors.'
        ] : [], 8)
      );
    }
    return {
      title: 'Official graph-based one- and two-step problems',
      sourceNote: solved ? 'Graph readings and comparison equations match the answer key.' : 'Source tables and bars remain visible; every requested student response remains open.',
      sections
    };
  }

  if (problemNumber === 1) {
    sections.push(
      table('Class straw measurements', ['Straw Owner', 'Nearest Inch', 'Nearest 1/2 Inch', 'Nearest 1/4 Inch'], Array.from({ length: 5 }, (_, index) => [
        index === 0 ? 'My straw' : '',
        solved ? 'class data' : '____',
        solved ? 'class data' : '____',
        solved ? 'class data ★ if exact' : '____'
      ])),
      response(solved ? 'Teacher Edition variable-data criteria' : 'Parts a–c remain open', solved ? [
        'Identify shortest and longest directly from the completed chart.',
        'Mark exact measurements with a star.',
        'The quarter-inch interval is most precise because it uses the smallest unit.'
      ] : [], 12)
    );
  } else if (problemNumber === 2) {
    const solvedTicks = ['0', '1/4', '1/2', '3/4', '1', '1 1/4', '1 1/2', '1 3/4', '2', '2 1/4', '2 1/2', '2 3/4', '3', '3 1/4', '3 1/2', '3 3/4', '4', '4 1/4', '4 1/2', '4 3/4', '5'];
    sections.push(
      line(
        solved ? 'Completed 5-inch paper strip' : 'Source 5-inch strip with whole- and half-inch tick topology',
        solved ? solvedTicks : Array.from({ length: 11 }, () => ''),
        solved ? solvedTicks.filter((tick) => tick.includes('/4') || tick.includes('/2')) : [],
        solved ? 'Whole, half, and quarter inches are labeled.' : 'Whole/half labels and estimated quarter-inch marks remain open.'
      ),
      response(solved ? 'Teacher Edition answer work' : 'Parts a–c remain open', solved ? [
        'a. Label whole and half inches from 0 through 5.',
        'b. 1 inch = 2 half inches; 1 inch = 4 quarter inches; 1/2 inch = 2 quarter inches.',
        'c. Move the strip end to end, recording each 5-inch length and the remaining part.'
      ] : [], 10)
    );
  } else {
    sections.push(response(solved ? 'Teacher Edition explanation' : 'Open words-pictures-numbers workspace', solved ? [
      '8 half inches = 4 inches because 2 half inches make 1 inch.'
    ] : [], 12));
  }
  return {
    title: 'Official ruler and measurement work',
    sourceNote: solved ? 'Only Teacher Edition fixed equivalences or variable-data criteria are shown.' : 'Blank preserves printed tick topology and leaves every requested label, mark, and response open.',
    sections
  };
}

function m6ReviewedLessonsSixThroughNineVisual(
  lessonNumber: number,
  problemNumber: number,
  sourcePrompt: string,
  solved: boolean
): ProblemVisualSpec | undefined {
  if (lessonNumber < 6 || lessonNumber > 9) {
    return undefined;
  }
  const sections: ProblemVisualSpec['sections'] = [];
  const table = (label: string, columns: string[], rows: string[][]): ProblemVisualSpec['sections'][number] => ({
    kind: 'data-table',
    label,
    columns,
    rows
  });
  const linePlot = (
    label: string,
    values: Array<{ label: string; value: number }>,
    showBlankValues: boolean,
    axisLabel: string,
    keyLabel: string,
    caption: string
  ): ProblemVisualSpec['sections'][number] => ({
    kind: 'line-plot',
    label,
    values,
    axisLabel,
    keyLabel,
    showBlankValues,
    caption
  });
  const pictureGraph = (
    label: string,
    values: Array<{ label: string; value: number; valueLabel?: string }>,
    showBlankValues: boolean,
    keyLabel: string
  ): ProblemVisualSpec['sections'][number] => ({
    kind: 'data-chart',
    chart: 'picture',
    label,
    values,
    unitSize: 4,
    keyLabel,
    showBlankValues,
    caption: solved
      ? 'Every symbol count matches the completed table.'
      : 'Category labels remain visible; the key and all symbols remain open.'
  });
  const response = (
    label: string,
    solvedLines: string[],
    printedLineCount: number
  ): ProblemVisualSpec['sections'][number] => ({
    kind: 'source-response-workspace',
    label,
    parts: [{
      prompt: sourcePrompt,
      lines: solved ? solvedLines : [],
      printedLineCount,
      openWorkspace: !solved
    }]
  });

  const teamHeights = [
    { label: '51', value: 2 },
    { label: '51 1/2', value: 0 },
    { label: '52', value: 3 },
    { label: '52 1/2', value: 1 },
    { label: '53', value: 2 },
    { label: '53 1/2', value: 3 },
    { label: '54', value: 1 },
    { label: '54 1/2', value: 2 },
    { label: '55', value: 1 }
  ];
  const wormLengths = [
    { label: '3', value: 1 },
    { label: '3 1/4', value: 2 },
    { label: '3 2/4', value: 4 },
    { label: '3 3/4', value: 6 },
    { label: '4', value: 8 },
    { label: '4 1/4', value: 4 },
    { label: '4 2/4', value: 3 },
    { label: '4 3/4', value: 0 },
    { label: '5', value: 2 }
  ];
  if (lessonNumber === 6) {
    if (problemNumber === 1) {
      sections.push(
        linePlot(
          'Heights of Children on Third-Grade Basketball Team',
          teamHeights,
          true,
          'Height in Inches',
          'X = 1 child',
          'This completed line plot is printed as the source data in both views.'
        ),
        response(solved ? 'Teacher Edition answer work' : 'Parts a–d remain open', [
          'a. 15; explanations will vary.',
          'b. 6',
          'c. No; explanations will vary.',
          'd. 4'
        ], 12)
      );
    } else {
      const displayedWorms = solved
        ? wormLengths.map((item) => ({ ...item, value: item.label === '4 3/4' ? 1 : item.value }))
        : wormLengths;
      sections.push(
        linePlot(
          solved ? 'Lengths of Worms after Madeline Adds Her Worm' : 'Lengths of Worms',
          displayedWorms,
          true,
          'Length in Inches',
          'X = 1 worm',
          solved
            ? 'The printed source data remain intact, with Madeline’s one new X added at 4 3/4 inches.'
            : 'This completed line plot is printed as the source data; no X is added at 4 3/4 inches yet.'
        ),
        response(solved ? 'Teacher Edition answer work' : 'Parts a–c remain open', [
          'a. 30; explanations will vary.',
          'b. No; explanations will vary.',
          'c. Length plotted correctly on line plot.'
        ], 10)
      );
    }
    return {
      title: problemNumber === 1
        ? 'Heights of Children on Third-Grade Basketball Team: official line plot'
        : 'Lengths of Worms: official line plot',
      sourceNote: solved
        ? 'The printed line-plot data and answer-key results match the Teacher Edition.'
        : 'Blank preserves every printed X, label, interval, and key; only the requested answers or new point are open.',
      sections
    };
  }

  const beanRows = [
    ['2 1/4', '2 3/4', '3 1/4', '1 3/4', '1 3/4'],
    ['1 3/4', '3', '2 1/2', '3 1/4', '2 1/2'],
    ['2', '2 1/4', '3', '2 1/4', '3'],
    ['2 1/2', '3 1/4', '1 3/4', '2 3/4', '2']
  ];
  const beanCounts = [
    { label: '1 3/4', value: 4 },
    { label: '2', value: 2 },
    { label: '2 1/4', value: 3 },
    { label: '2 1/2', value: 3 },
    { label: '2 3/4', value: 2 },
    { label: '3', value: 3 },
    { label: '3 1/4', value: 3 }
  ];
  if (lessonNumber === 7) {
    sections.push(
      table('Heights of Bean Plants (in Inches)', ['Measurement 1', 'Measurement 2', 'Measurement 3', 'Measurement 4', 'Measurement 5'], beanRows),
      linePlot(
        solved ? 'Heights of Bean Plants' : 'Official empty quarter-inch line plot',
        solved ? beanCounts : beanCounts.map((item) => ({ ...item, value: 0 })),
        solved,
        solved ? 'inches' : 'Label: ____________________',
        solved ? 'X = 1 bean plant' : 'X = ______',
        solved
          ? 'All 20 source measurements are plotted at quarter-inch intervals.'
          : 'The title, key, and all Xs remain open exactly as requested.'
      ),
      response(solved ? 'Teacher Edition answer work' : 'Parts b–f remain open', [
        'a. Line plot completed; Heights of Bean Plants; inches; values for X may vary.',
        'b. 14',
        'c. 6',
        'd. 1 3/4 inches; 4',
        'e. No; explanations will vary.',
        'f. Yes; explanations will vary.'
      ], 16)
    );
    return {
      title: 'Heights of Bean Plants: official quarter-inch data and line plot',
      sourceNote: solved
        ? 'The line plot and all fixed answers match the Teacher Edition answer key.'
        : 'All 20 printed measurements remain visible; the line plot and response spaces remain empty.',
      sections
    };
  }

  const leafRows = [
    ['5 3/4', '6', '6 1/4', '6', '5 3/4'],
    ['6 1/2', '6 1/4', '5 1/2', '5 3/4', '6'],
    ['6 1/4', '6', '6', '6 1/2', '6 1/4'],
    ['6 1/2', '5 3/4', '6 1/4', '6', '6 3/4'],
    ['6', '6 1/4', '6', '5 3/4', '6 1/2']
  ];
  const leafCounts = [
    { label: '5 1/2', value: 1 },
    { label: '5 3/4', value: 5 },
    { label: '6', value: 8 },
    { label: '6 1/4', value: 6 },
    { label: '6 1/2', value: 4 },
    { label: '6 3/4', value: 1 }
  ];
  if (lessonNumber === 8) {
    sections.push(
      table('Widths of Silver Maple Tree Leaves (in Inches)', ['Measurement 1', 'Measurement 2', 'Measurement 3', 'Measurement 4', 'Measurement 5'], leafRows),
      linePlot(
        solved ? 'Widths of Leaves' : 'Official empty quarter-inch line plot',
        solved ? leafCounts : leafCounts.map((item) => ({ ...item, value: 0 })),
        solved,
        solved ? 'inches' : 'Label: ____________________',
        solved ? 'X = 1 leaf' : 'X = ______',
        solved
          ? 'All 25 source measurements are plotted at quarter-inch intervals.'
          : 'The title, key, labels, and all Xs remain open exactly as requested.'
      ),
      response(solved ? 'Teacher Edition answer work' : 'Parts b–d remain open', [
        'a. Line plot completed; Widths of Leaves; inches; values for X may vary.',
        'b. Answers will vary.',
        'c. 4',
        'd. Explanations will vary.'
      ], 14)
    );
    return {
      title: 'Widths of Silver Maple Tree Leaves: official data and line plot',
      sourceNote: solved
        ? 'The line plot and answer-key results match the Teacher Edition.'
        : 'All 25 printed measurements remain visible; the line plot and response spaces remain empty.',
      sections
    };
  }

  const appleRows = solved
    ? [['Stewart', '16'], ['Roxanne', '24'], ['Trisha', '12'], ['Philip', '20'], ['Total', '72']]
    : [['Stewart', '16'], ['Roxanne', '____'], ['Trisha', '12'], ['Philip', '20'], ['Total', '72']];
  const appleValues = [
    { label: 'Stewart', value: solved ? 16 : 0, valueLabel: solved ? '16' : '____' },
    { label: 'Roxanne', value: solved ? 24 : 0, valueLabel: solved ? '24' : '____' },
    { label: 'Trisha', value: solved ? 12 : 0, valueLabel: solved ? '12' : '____' },
    { label: 'Philip', value: solved ? 20 : 0, valueLabel: solved ? '20' : '____' }
  ];
  const grassRows = [
    ['2 1/4', '2 3/4', '3 1/4', '3', '2 1/2', '2 3/4'],
    ['2 3/4', '3 3/4', '2', '2 3/4', '3 3/4', '3 1/4'],
    ['3', '2 1/2', '3 1/4', '2 1/4', '2 3/4', '3'],
    ['3 1/4', '2 1/4', '3 3/4', '3', '3 1/4', '2 3/4']
  ];
  const grassCounts = [
    { label: '2', value: 1 },
    { label: '2 1/4', value: 3 },
    { label: '2 1/2', value: 2 },
    { label: '2 3/4', value: 6 },
    { label: '3', value: 4 },
    { label: '3 1/4', value: 5 },
    { label: '3 1/2', value: 0 },
    { label: '3 3/4', value: 3 }
  ];
  if (problemNumber === 1) {
    sections.push(
      table('Official apple-picking chart', ['Name', 'Number of Apples Picked'], appleRows),
      pictureGraph(
        solved ? 'Completed Apples Picked picture graph' : 'Official empty Apples Picked picture graph',
        appleValues,
        solved,
        solved ? 'Each symbol represents 4 apples.' : 'Each symbol represents ______ apples.'
      ),
      response(solved ? 'Teacher Edition answer work' : 'Parts a–b remain open', [
        'a. 24',
        'b. Picture graph completed; scale drawn.'
      ], 8)
    );
  } else if (problemNumber === 2) {
    sections.push(
      table(
        solved ? 'Completed Problem 1 chart retained as the given' : 'Problem 1 chart or graph retained as the given',
        ['Name', 'Number of Apples Picked'],
        solved
          ? appleRows
          : [['Stewart', '16'], ['Roxanne', 'student result from Problem 1'], ['Trisha', '12'], ['Philip', '20'], ['Total', '72']]
      ),
      response(solved ? 'Teacher Edition answer work' : 'Parts a–b remain open', [
        'a. 8',
        'b. 4'
      ], 10)
    );
  } else {
    sections.push(
      table('Lengths of Blades of Grass (in Inches)', ['Measurement 1', 'Measurement 2', 'Measurement 3', 'Measurement 4', 'Measurement 5', 'Measurement 6'], grassRows),
      linePlot(
        solved ? 'Lengths of Blades of Grass' : 'Official empty quarter-inch line plot',
        solved ? grassCounts : grassCounts.map((item) => ({ ...item, value: 0 })),
        solved,
        'Length in Inches',
        'X = 1 blade of grass',
        solved
          ? 'All 24 printed measurements are plotted at quarter-inch intervals.'
          : 'Choose the scale, then plot the 24 printed measurements; no X is pre-seeded.'
      ),
      response(solved ? 'Teacher Edition answer work' : 'Parts a–d remain open', [
        'a. Line plot completed; explanations will vary.',
        'b. 24; explanations will vary.',
        'c. 2 3/4 inches; 6',
        'd. 2'
      ], 14)
    );
  }
  return {
    title: problemNumber === 3
      ? 'Lengths of Blades of Grass: official data and line plot'
      : 'Apples Picked: official chart and picture-graph work',
    sourceNote: solved
      ? 'Fixed values and answers match the Teacher Edition answer key.'
      : 'Blank retains only printed givens and prior-problem dependencies; every requested entry, symbol, scale, and response remains open.',
    sections
  };
}

function m6ProblemVisual(
  lessonNumber: number,
  problemNumber: number,
  visualFamily: string,
  display: ProblemSetDataDisplay,
  equations: string[],
  sourcePrompt: string,
  solvedAnswer: string | undefined,
  solved: boolean
): ProblemVisualSpec {
  const reviewedVisual = m6ReviewedLessonsOneThroughFiveVisual(
    lessonNumber,
    problemNumber,
    sourcePrompt,
    solvedAnswer,
    solved
  );
  if (reviewedVisual) {
    return reviewedVisual;
  }
  const reviewedVisualSixThroughNine = m6ReviewedLessonsSixThroughNineVisual(
    lessonNumber,
    problemNumber,
    sourcePrompt,
    solved
  );
  if (reviewedVisualSixThroughNine) {
    return reviewedVisualSixThroughNine;
  }
  const sections: ProblemVisualSpec['sections'] = [];
  const displayRows = m6VisualRows(lessonNumber, problemNumber, display, solved);
  if (lessonNumber === 5 && problemNumber === 1) {
    sections.push({
      kind: 'data-table',
      label: 'Class straw measurements',
      columns: ['Straw owner', 'Nearest inch', 'Nearest 1/2 inch', 'Nearest 1/4 inch'],
      rows: Array.from({ length: 4 }, (_, index) => [
        index === 0 ? 'My straw' : `Classmate ${index}`,
        solved ? 'class data' : '____',
        solved ? 'class data' : '____',
        solved ? 'class data ★ if exact' : '____'
      ])
    });
  }
  const usesPurposeBuiltSourceTable = lessonNumber === 5 && problemNumber === 1;
  const usesGraphWithTransferredNumberLine = lessonNumber === 3 && problemNumber === 4;
  if (displayRows.length && !usesPurposeBuiltSourceTable && !usesGraphWithTransferredNumberLine) {
    sections.push({
      kind: 'data-table',
      label: `${display.title} source data`,
      columns: m6VisualColumns(display, displayRows),
      rows: displayRows
    });
  }

  if (display.kind === 'data-table' && /bar graph|picture graph|scaled/i.test(visualFamily)) {
    sections.push({
      kind: 'data-chart',
      chart: /picture/i.test(visualFamily) ? 'picture' : 'bar',
      label: `${display.title} graph workspace`,
      values: displayRows.slice(0, 8).map((row) => ({
        label: row[0] ?? 'category',
        value: Number.isFinite(Number(row[1])) ? Number(row[1]) : undefined,
        valueLabel: solved ? row[1] : '____',
        target: solved
      })),
      maxValue: Math.max(1, ...displayRows.map((row) => Number(row[1]) || 0)),
      scaleLabel: display.scaleLabel ?? 'Use the stated equal-interval scale.',
      keyLabel: display.keyLabel,
      showBlankValues: solved,
      caption: solved ? 'Bars match the table values and scale.' : 'Draw each bar from the source table using equal intervals.'
    });
  } else if (display.kind === 'line-plot') {
    sections.push({
      kind: 'line-plot',
      label: display.title,
      values: (display.values ?? []).map((item) => ({
        label: item.label,
        value: item.value,
        valueLabel: item.valueLabel,
        target: solved && Boolean(item.value)
      })),
      axisLabel: display.axisLabel,
      keyLabel: display.keyLabel,
      showBlankValues: solved || display.showBlankValues,
      caption: solved
        ? display.keyLabel ?? 'Read each X as one measurement.'
        : 'Use the source data to place Xs above the correct measurement labels.'
    });
  } else if (display.kind === 'ruler') {
    sections.push({
      kind: 'number-line',
      label: display.title,
      ticks: (display.ticks ?? []).map((tick) => ({
        label: tick,
        target: solved && (tick.includes('/2') || tick.includes('/4'))
      })),
      caption: solved
        ? 'Whole inches, half inches, and quarter inches are labeled on the same strip.'
        : 'Label the whole, half, and quarter-inch marks before measuring.'
    });
  } else if (display.kind === 'vertical-tape') {
    sections.push({
      kind: 'card-grid',
      label: `${display.title} vertical tapes`,
      cards: (display.values ?? []).map((item) => {
        const units = m6VisualUnitCount(item.value, display);
        return {
          label: item.label,
          sections: [{
            kind: 'tape',
            label: item.label,
            totalLabel: solved && item.value !== undefined ? `${item.value} ${m6DisplayUnitLabel(display)}` : `${item.label}: ____`,
            parts: Array.from({ length: units }, (_, index) => ({
              label: solved ? String(display.unitSize ?? display.interval ?? index + 1) : '',
              emphasize: solved && index < units
            })),
            caption: solved
              ? `${item.label} is represented by ${item.value} using the stated scale/key.`
              : `Use the stated scale/key to complete ${item.label}.`
          }]
        };
      })
    });
  } else if (display.kind === 'bar-graph' || display.kind === 'picture-graph') {
    const chartValues = display.values?.length
      ? display.values
      : (display.categories ?? []).map((label) => ({ label, value: undefined, valueLabel: solved ? 'class data' : '____' }));
    sections.push({
      kind: 'data-chart',
      chart: display.kind === 'bar-graph' ? 'bar' : 'picture',
      label: display.title,
      values: chartValues.map((item) => ({
        label: item.label,
        value: item.value,
        valueLabel: item.valueLabel,
        target: solved && item.value !== undefined
      })),
      maxValue: display.maxValue,
      unitSize: display.unitSize,
      scaleLabel: display.scaleLabel,
      keyLabel: display.keyLabel,
      showBlankValues: solved || display.showBlankValues,
      caption: solved
        ? display.scaleLabel ?? display.keyLabel ?? 'Read each category with the official scale/key.'
        : display.scaleLabel ?? display.keyLabel ?? 'Preserve the source graph labels, categories, and response blanks.'
    });
  } else if (display.kind === 'tally-picture') {
    sections.push({
      kind: 'data-chart',
      chart: 'tally',
      label: display.title,
      values: (display.categories ?? []).map((category) => ({ label: category, valueLabel: solved ? 'class data' : '____' })),
      keyLabel: display.keyLabel,
      showBlankValues: false,
      caption: 'Use the class survey data, bundle tallies by fives, then convert counts to picture-graph symbols.'
    });
  }

  if (lessonNumber === 3 && problemNumber === 4) {
    sections.push({
      kind: 'number-line',
      label: 'Charlotte’s Reading Minutes number line',
      ticks: ['0', '10', '20', '30', '40', '50', '60', '70'].map((label) => ({
        label,
        target: solved && ['40', '50', '70'].includes(label)
      })),
      caption: solved
        ? 'Plot Monday 50, Tuesday 50, Wednesday 70, Thursday 50, and Friday 40.'
        : 'Use the graph grid as a ruler to mark equal 10-minute intervals, then plot and label each day.'
    });
  }

  const equationLines = solved
    ? m6SolvedVisualEquations(equations, solvedAnswer)
    : m6BlankEquationTemplates(equations, visualFamily);
  sections.push({
    kind: 'equations',
    label: solved ? 'Teacher Edition answer work' : 'Student work blanks',
    lines: equationLines
  });
  if (sections.length < 3) {
    sections.push({
      kind: 'note',
      label: solved ? 'Solved check' : 'Source workspace direction',
      text: solved
        ? solvedAnswer ?? 'Teacher Edition accepts variable student data when the display, scale, labels, and explanation match the official problem.'
        : `Complete the ${visualFamily}: keep the labels, scale/key, intervals, and answer blanks ready for student work.`
    });
  }

  return {
    title: `${display.title}: ${visualFamily}`,
    sourceNote: solved
      ? 'Solved view shows the completed source data display, scale/key, and answer evidence.'
      : 'Blank view preserves the source labels, scale/key, intervals, and student response spaces.',
    sections
  };
}

function m6VisualColumns(display: ProblemSetDataDisplay, rows: string[][]): string[] {
  if (display.sourceDataRows?.length && rows[0]?.length) {
    return Array.from({ length: rows[0].length }, (_, index) => `Measurement ${index + 1}`);
  }
  if (display.columns?.length) {
    return display.columns;
  }
  if (display.kind === 'line-plot') {
    return ['Measurement', 'Number of Xs'];
  }
  if (display.kind === 'ruler') {
    return ['Mark', 'Measurement interval'];
  }
  return ['Label', 'Value'];
}

function m6VisualRows(
  lessonNumber: number,
  problemNumber: number,
  display: ProblemSetDataDisplay,
  solved: boolean
): string[][] {
  if (display.rows?.length) {
    return display.rows.map((row) => row.map((cell) => m6SolvedCell(lessonNumber, problemNumber, cell, solved)));
  }
  if (display.sourceDataRows?.length) {
    return display.sourceDataRows;
  }
  if (display.values?.length) {
    return display.values.map((item) => [
      item.label,
      solved && item.value !== undefined ? String(item.value) : item.valueLabel ?? '____'
    ]);
  }
  if (display.ticks?.length) {
    return display.ticks.map((tick) => [tick, solved ? m6RulerMarkMeaning(tick) : '____']);
  }
  if (display.categories?.length) {
    return display.categories.map((category) => [
      category,
      solved ? m6SolvedCell(lessonNumber, problemNumber, '____', true) : '____'
    ]);
  }
  return [[display.title, solved ? 'Use the completed display to explain the answer.' : 'Set up the display labels, scale/key, and answer blanks.']];
}

function m6SolvedCell(lessonNumber: number, problemNumber: number, cell: string, solved: boolean): string {
  if (!solved) {
    return cell;
  }
  if (lessonNumber === 1 && cell === '____') {
    if (problemNumber === 1) {
      return 'class tally count';
    }
    if (problemNumber === 2) {
      return 'read from Problem 1';
    }
    return 'converted from class data';
  }
  if (lessonNumber === 5 && cell === '____') {
    return problemNumber === 1 ? 'student measurement' : 'unit equivalence';
  }
  if (lessonNumber === 9 && (problemNumber === 1 || problemNumber === 2) && cell === '____') {
    return '24';
  }
  return cell;
}

function m6VisualUnitCount(value: number | undefined, display: ProblemSetDataDisplay): number {
  if (!value) {
    return 4;
  }
  const unit = display.unitSize ?? display.interval ?? 1;
  return Math.max(1, Math.min(16, Math.ceil(value / unit)));
}

function m6DisplayUnitLabel(display: ProblemSetDataDisplay): string {
  if (display.title.includes('Apples')) {
    return 'apples';
  }
  if (display.title.includes('Visitors')) {
    return 'visitors';
  }
  if (display.title.includes('Savings')) {
    return 'dollars';
  }
  if (display.title.includes('Students')) {
    return 'students';
  }
  if (display.title.includes('Stamps')) {
    return 'stamps';
  }
  return 'units';
}

function m6SolvedVisualEquations(equations: string[], solvedAnswer: string | undefined): string[] {
  const lines = equations.length ? equations : [];
  if (solvedAnswer) {
    return Array.from(new Set([...lines, ...solvedAnswer.split(/;\s+/).map((line) => line.trim()).filter(Boolean)])).slice(0, 8);
  }
  return lines.length ? lines : ['Variable answer: verify the display, scale, labels, and written explanation against the Teacher Edition.'];
}

function m6RulerMarkMeaning(tick: string): string {
  if (tick === '0') {
    return 'start';
  }
  if (tick.includes('/4')) {
    return 'quarter-inch mark';
  }
  if (tick.includes('/2')) {
    return 'half-inch mark';
  }
  return 'whole-inch mark';
}

