function m7VisualFamily(lessonNumber: number): string {
  if (lessonNumber <= 2 || lessonNumber === 15 || lessonNumber === 23) {
    return 'RDW word-problem model';
  }
  if (lessonNumber === 3) {
    return 'RDW strategy-comparison model';
  }
  if (lessonNumber === 17) {
    return 'composite perimeter workspace';
  }
  if (lessonNumber === 28 || lessonNumber === 29) {
    return 'area and perimeter workspace';
  }
  if (lessonNumber === 30 || lessonNumber >= 33) {
    return 'critique and reflection tool';
  }
  if (lessonNumber <= 6) {
    return 'polygon attribute workspace';
  }
  if (lessonNumber <= 9) {
    return 'polygon composition workspace';
  }
  if (lessonNumber === 16) {
    return 'circular-object perimeter workspace';
  }
  if (lessonNumber <= 16) {
    return 'perimeter shape workspace';
  }
  if (lessonNumber === 19 || lessonNumber === 22) {
    return 'line plot workspace';
  }
  if (lessonNumber >= 18 && lessonNumber <= 21) {
    return 'area and perimeter grid workspace';
  }
  if (lessonNumber >= 24 && lessonNumber <= 27) {
    return 'robot measurement project workspace';
  }
  if (lessonNumber === 31 || lessonNumber === 32) {
    return 'one-half representation workspace';
  }
  return 'Teacher Edition workspace';
}

function m7TeacherAnswerEvidence(answer: string | undefined, fallback: string[]): string[] {
  if (!answer) {
    return fallback;
  }

  const evidence = answer
    .split(/;\s+|(?=\b[a-g]\.\s)/)
    .map((part) => part.trim())
    .filter(Boolean)
    .slice(0, 8);

  return evidence.length ? evidence : [answer];
}

function m7MaskBlankEquation(equation: string): string {
  return equation
    .replace(/×/g, 'x')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\$\s*\d[\d,]*(?:\.\d+)?/g, '$____')
    .replace(/\b\d[\d,]*(?:\.\d+)?\b/g, '____');
}

function m7BlankEquationTemplates(sourceEquations: string[], visualFamily: string): string[] {
  const templates = sourceEquations
    .map((equation) => equation.includes('____') ? equation.replace(/×/g, 'x').replace(/\s+/g, ' ').trim() : m7MaskBlankEquation(equation))
    .filter(Boolean);

  return templates.length
    ? Array.from(new Set(templates))
    : [`Use the official ${visualFamily} blanks, labels, units, and response lines.`];
}

