  '20-2': "Use your square unit tiles to build as many rectangles as you can with a perimeter of 14 units. a. Draw and label the side lengths. b. Find the areas. c. Given a rectangle's perimeter, what other information do you need to know to find its area?",
  '21-1': 'On your centimeter grid paper, shade and label as many rectangles as you can with a perimeter of 16 centimeters. a. Sketch the rectangles below, and label the side lengths. b. Find the area of each rectangle you drew above.',
