  '21-3': 'Use centimeter grid paper to shade in as many rectangles as you can with the given perimeters. a. Use the charts below to show how many rectangles you shaded for each given perimeter. You might not use all the spaces in the charts. b. Did you make a square with either of the given perimeters? How do you know?',
  '21-4': "Macy and Gavin both draw rectangles with perimeters of 16 centimeters. Use words and pictures to explain how it is possible for Macy's and Gavin's rectangles to have the same perimeters but different areas.",
  '22-1': 'Use the data you gathered from your Problem Sets to create a line plot for the number of rectangles you created with each given perimeter.',
  '22-2': 'Why are all of the perimeter measurements even? Do all rectangles have an even perimeter?',
  '22-3': 'Compare the two line plots we created. Is there any reason to think that knowing only the area of a rectangle would help you to figure out its perimeter or knowing only the perimeter of a rectangle would help you figure out its area?',
  '22-4': 'Sumi uses unit square tiles to build 3 rectangles that have an area of 32 square units. Does knowing this help her find the number of rectangles she can build for a perimeter of 32 units? Why or why not?',
