  '23-1': 'Gale makes a miniature stop sign, a regular octagon, with a perimeter of 48 centimeters for the town he built with blocks. What is the length of each side of the stop sign?',
  '23-2': 'Travis bends wire to make rectangles. Each rectangle measures 34 inches by 12 inches. What is the total length of the wire needed for two rectangles?',
  '23-3': 'The perimeter of a rectangular bathroom is 32 feet. The width of the room is 8 feet. What is the length of the room?',
  '23-4': 'Raj uses 6-inch square tiles to make a rectangle, as shown below. What is the perimeter of the rectangle in inches?',
  '23-5': 'Mischa makes a 4-foot by 6-foot rectangular banner. She puts ribbon around the outside edges. The ribbon costs $2 per foot. What is the total cost of the ribbon?',
  '23-6': 'Colton buys a roll of wire fencing that is 120 yards long. He uses it to fence in his 18-yard by 24-yard rectangular garden. Will Colton have enough wire fencing left over to fence in a 6-yard by 8-yard rectangular play space for his pet rabbit?',
  '24-1': "Use the given perimeters in the chart below to choose the widths and lengths of your robot's rectangular body parts. Write the widths and lengths in the chart. Use the blank rows if you want to add extra rectangular body parts. Your robot should have 7 to 9 rectangular body parts. Then use the environment chart to plan 6 to 8 items for your robot's environment, including rectangular and circular items with the listed perimeter requirements.",
  '25-1': 'Draw a picture of your robot in its environment in the space below. Label the widths, lengths, and perimeters of all rectangles. Label the perimeters of all circular shapes.',
  '26-1': "Collect the area measurements of your classmates' robot bodies. Make a line plot using everyone's area measurements. a. How many different measurements are on the line plot? Why are the measurements different? b. What does this tell you about the relationship between area and perimeter?",
  '26-2': 'Measure and calculate the perimeter of your construction paper in inches. Show your work below.',
  '26-3': "Sketch and label two shapes with the same perimeter from the robot's environment. What do you notice about the way they look?",
